"""Bilingual review generated from completed P1 raw-derived records; P0 remains historical."""
import json,math,html,collections,datetime
from pathlib import Path
CASE=Path(__file__).resolve().parents[2];R=CASE/'results/p1_r2'
def main():
 d=json.loads((R/'derived_summary.json').read_text());rows=d['rows'];audit=json.loads((R/'independent_audit.json').read_text());receipt=json.loads((R/'worker_receipt.json').read_text());selection=json.loads((R/'fit_frozen.json').read_text())['selected'];freeze=json.loads((R/'code_freeze.json').read_text())['code_freeze_sha256'];classifications=json.loads((R/'classifications.json').read_text());robust=json.loads((R/'arithmetic_sign_robustness.json').read_text())['rows']
 assert audit['core_cells']==30
 sels=sorted([r for r in rows if r['selected_CAL'] and r['split']=='EVAL-ID'],key=lambda r:(r['block'],r['projection']))
 get=lambda b,p,s,a:next(q for q in rows if (q['block'],q['projection'],q['split'],q['alpha'])==(b,p,s,a))
 counts={s:collections.Counter(k for r in classifications if r['split']==s and r['alpha'] for k in r['labels']) for s in ['CAL-FIT','DEV-SELECT','EVAL-ID','SHIFT']}
 decision={'run_id':'p1_r2','status':'REVIEW_READY','P0':'PRESERVED_HISTORICAL_PASS','P0_MC_RERUN':False,'P0_C_lambda':0,'P1':'COMPLETED_FULL','core_cells':30,'failed_core_cells':0,'missing_core_cells':0,'raw_core_rows':2880,'unique_documents_excluding_smoke':96,'EVAL_ID_original_books':32,'SHIFT_content_groups':16,'total_model_forwards':3845,'conservative_worker_wall_seconds':receipt['wall_seconds'],'model_source':'USER_AUTHORIZED_EXISTING_WSL_SNAPSHOT_READ_ONLY','identity_level':'LOCAL_IDENTITY_VERIFIED; full weight hash matches existing blob identity, no new official digest lookup','execution_source_sha256':freeze,'Q1':'One fixed-B cancellation-loss FP64 pattern; its BF16 interpretation remains arithmetic-bound ambiguous. Not a prevalence or causal proof.','Q2':'12 FP64 re-quantization reversal patterns (4 EVAL,8 DEV); actual saved artifacts. Small runtime effects separately flagged.','Q3':'All six CAL-selected strengths increase aggregate EVAL local SSE; EVAL NLL3 lower/3 higher, SHIFT NLL6 higher point estimates.','P2':'NOT_RUN_SCOPE','P3':'NOT_RUN_SCOPE','SERVING_BENEFIT':'NOT_ESTABLISHED','remote_publication':'NOT_RUN_SCOPE','classification_counts_FP64':d['classification_counts'],'arithmetic_delta_sign_certified':sum(r['algebra_sign_certified_against_arithmetic_bound'] for r in robust),'arithmetic_delta_sign_total':len(robust),'scope':'single model/revision, fixed6 target interventions, one CAL draw,256-token teacher-forced documents; exploratory pointwise intervals'}
 (R/'decision.json').write_text(json.dumps(decision,indent=2))
 for lang in ['ko','en']:
  ko=lang=='ko';suffix='.ko' if ko else '';title='Case014 — 양자화 오차 보정의 상쇄·재양자화·일반화 분석' if ko else 'Case014 — Quantization Compensation: Cancellation, Re-quantization, and Generalization'
  intro=('보정값 계산부터 INT4 저장·재로딩, 오차 분해, 동일 입력의 전체 모델 비교까지 실행했습니다. CAL에서 고른 강도는 국소 오차를 줄였지만, 새 EVAL 문서에서는 여섯 표적 모두의 합산 국소 오차가 증가했습니다. 모델의 다음 토큰 점수는 표적에 따라 다르게 움직였습니다.' if ko else 'Executed correction fitting, INT4 save/reload, error decomposition and common-input full-model comparison. CAL-selected strengths reduced local error on CAL, but increased aggregate local error on new EVAL documents at all six targets. Next-token scores moved differently across targets.')
  easy=('양자화는 모델의 숫자를 적은 비트로 저장하는 방법입니다. 보정은 앞부분에서 전달된 오차를 줄이도록 뒤쪽 가중치를 조정합니다. 이 도구는 그 조정값도 다시 INT4로 저장했을 때 무엇이 남고, 새로운 문서에서도 도움이 되는지 확인합니다.' if ko else 'Quantization stores model numbers using fewer bits. Compensation adjusts later weights to reduce error inherited from earlier layers. This tool checks what survives after those adjusted weights are stored as INT4 again, and whether the benefit transfers to other documents.')
  head=['배경','질문·가설','이론과 구현 계약','방법','실험','결과','분석','결론','재현과 참고자료'] if ko else ['Background','Questions','Theory and implementation contract','Method','Experiments','Results','Analysis','Conclusion','Reproduction and references']
  table=['|Block / projection|CAL α|CAL ΔSSE %|EVAL ΔSSE %|EVAL ΔNLL [95% CI]|SHIFT ΔNLL [95% CI]|','|---|---:|---:|---:|---|---|'];html_selected=''
  for r in sels:
   b,p,a=r['block'],r['projection'],r['alpha'];cal=get(b,p,'CAL-FIT',a);shift=get(b,p,'SHIFT',a)
   fmt=lambda q:f"{q['DeltaNLL_vs_alpha0_doc_mean']:+.6f} [{q['DeltaNLL_pointwise_CI95'][0]:+.6f}, {q['DeltaNLL_pointwise_CI95'][1]:+.6f}]"
   table.append(f"|{b} / {p}|{a:g}|{cal['DeltaSSE_percent']:+.2f}|{r['DeltaSSE_percent']:+.2f}|{fmt(r)}|{fmt(shift)}|")
   html_selected+=f"<tr><td>{b} / {p}</td><td>{a:g}</td><td>{cal['DeltaSSE_percent']:+.2f}%</td><td>{r['DeltaSSE_percent']:+.2f}%</td><td>{r['DeltaNLL_vs_alpha0_doc_mean']:+.6f}</td><td>{shift['DeltaNLL_vs_alpha0_doc_mean']:+.6f}</td></tr>"
  table='\n'.join(table)
  class_table=['|Split|Comparisons (nonzero α)|A|B|C|D|','|---|---:|---:|---:|---:|---:|']
  for split,denom in [('CAL-FIT',768),('DEV-SELECT',384),('EVAL-ID',768),('SHIFT',384)]:
   c=counts[split];class_table.append(f"|{split}|{denom}|{c['A_CANCELLATION_LOSS']}|{c['B_REQUANTIZATION_REVERSAL']}|{c['C_CONTINUOUS_TRANSFER_LOSS']}|{c['D_LOCAL_NLL_DISAGREEMENT']}|")
  class_table='\n'.join(class_table)
  contract='''W[out,in], X/Z[in,tokens]. CAL only: G=ZZᵀ, λ=0.001 trace(G)/d; (G+λI)Kᵀ=[W(X−Z)Zᵀ]ᵀ; δW=αK; W*=W+δW.

A=W(X−Z), C=δWZ, B=(What−W*)Z, B₀=(What₀−W)Z, R=A−C−B, R₀=A−B₀.

Δ=||R||²−||R₀||²=T_inherited+T_cancellation+T_requant.

T_inherited=||C||²−2⟨A,C⟩; T_cancellation=2⟨B₀,C⟩; T_cont=||C||²−2⟨R₀,C⟩; T_requant=||B−B₀||²−2⟨R₀−C,B−B₀⟩.'''
  protocol=('원형 BF16 projection 입력 X와 선행 블록만 RTN으로 바꾼 Z를 실제 full forward에서 캡처했습니다. 표적은 block4/12/20의 o_proj/down_proj, 강도는0/0.25/0.5/0.75/1입니다. 표적 하나씩 독립 개입하고 나머지 같은 블록·suffix는 원형으로 유지했습니다.\n\nCAL32책에서 CPU FP64 full Gram/Cholesky/삼각 solve와 row chunk128을 사용했습니다. 여섯 K·lambda와 30개 artifact·선택 강도를 동결한 뒤 비CAL 문서를 열었습니다. DEV에서 재선택하지 않았고, EVAL 최적 강도는 사후 oracle로만 남겼습니다.\n\n각 문서는256토큰, 다음255토큰 NLL/argmax flip, 고정16위치의 full-vocabulary KL입니다. chat/BOS/EOS 추가 없이 batch1, use_cache=False, SDPA, TF32 및 BF16 reduced reduction=False, 전체256위치 LM head를 공통 사용했습니다.' if ko else 'Captured teacher projection inputs X and hybrid-prefix inputs Z using actual full-model forwards. Targets are o_proj/down_proj in blocks4/12/20; strengths are0/0.25/0.5/0.75/1. Each target is intervened on separately, preserving its other block operations and suffix.\n\nCAL fitting used CPU FP64 full-input Gram, Cholesky, triangular solves and row chunks128. All six K/lambda values,30 artifacts and selected strengths froze before non-CAL forwards. DEV performed no reselection; EVAL-best strengths remain post-hoc oracles.\n\nEach256-token document contributes255 next-token NLL/flip positions and16 fixed full-vocabulary KL positions. No added chat/BOS/EOS; batch1, use_cache=False, SDPA, TF32 and BF16 reduced reduction disabled, with the same full256-position LM head.')
  boundary=('W*를 FP32로 바꿔 signed INT4[-8,7], input group64, output-row별 FP32 absmax/7, nearest-even으로 재양자화했습니다. low-nibble-first, header36B, zero-group scale1 규칙입니다. 실제 파일을 저장·읽은 What(FP32)를 대수에, BF16(What)를 실제 모델에 사용했습니다. 양자화 코드·scale 계산과 fit/scorer는 P0 준비본과 동일합니다.\n\n이것은 packed INT4 **저장 + dense BF16 품질 reference**입니다. K를 런타임 추가 연산으로 붙이지 않았습니다. FP32 연속 대조는 FP32 가중치·입력과 BF16 출력 cast를 사용한 별도 진단이며 상한이 아닙니다.' if ko else 'FP32(W*) was re-quantized to signed INT4[-8,7], input group64, output-row FP32 absmax/7 scales and nearest-even rounding. The format uses low-nibble-first packing, a36-byte header and unit scales only for zero groups. Algebra uses the actual reloaded FP32 What; model execution uses BF16(What). Quantization, fitting and scoring remained unchanged from preparation.\n\nThis is packed INT4 storage plus dense BF16 quality reference execution. K is not an extra runtime operation. Continuous controls use FP32 weights/inputs and BF16 output casts; they are separate diagnostics, not upper bounds.')
  dataset=('PG19의 서로 다른 book URL로 CAL32/DEV16/EVAL32를 나누고, Pile ArXiv16개 content group을 SHIFT로 사용했습니다. 별도 SMOKE1은 평가 분모에서 제외합니다. 동일 문서·token hash·offset·mask·position을 유지했습니다. Pile 원 논문 ID가 없어 article-disjoint를 보장하지 않으며, 조사 범위 밖의 과거 사용과 사전학습 노출은 미확인입니다.\n\n핵심30조건×96문서=2,880행입니다. 이는 독립 문서2,880개가 아닙니다. EVAL의 독립 단위는32책, SHIFT는16 content group입니다. 전체 forward3,845회에는 teacher·prefix·smoke·연속 대조가 포함됩니다.' if ko else 'Distinct PG19 book URLs define CAL32/DEV16/EVAL32;16 Pile ArXiv content groups define SHIFT. One separate smoke input is excluded from evaluation denominators. Document/token hashes, offsets, masks and positions were retained. Original Pile article IDs are unavailable; article-disjointness, prior use beyond the bounded audit and pretraining exposure remain unverified.\n\nThirty core settings ×96 documents produce2,880 rows, not2,880 independent documents. EVAL has32 books; SHIFT has16 content groups. The3,845 forwards include teacher, prefix, smoke and continuous controls.')
  findings=('표의 Δ는 같은 표적의 alpha0 대비입니다. 각 baseline은 선행 블록과 해당 표적만 RTN으로 바꾼 hybrid 모델이며, 전체 모델 RTN 또는 과거 Case013 baseline과 다릅니다. SSE는 합산 국소 오차, NLL은 nats/token이며 둘 다 음수 변화가 개선입니다.\n\nCAL 선택값의 EVAL 합산 SSE는6/6에서 증가했습니다. EVAL NLL은 o_proj3개에서 감소, down_proj3개에서 증가했습니다. SHIFT NLL은6/6에서 증가한 점추정치입니다. 일부 NLL 구간은0을 포함합니다. 아래 구간은 문서 pair10,000회 bootstrap, seed6101516의 탐색적 pointwise95% 구간입니다.' if ko else 'Deltas compare against alpha0 at the same target. Each baseline is a hybrid with RTN preceding blocks and target, not whole-model RTN or the historical Case013 baseline. SSE is aggregate local error; NLL is nats/token. Negative changes improve the respective metric.\n\nCAL-selected EVAL aggregate SSE increased at6/6 targets. EVAL NLL decreased at the three o_proj targets and increased at the three down_proj targets. SHIFT NLL point estimates increased at6/6; some intervals include zero. Intervals are exploratory pointwise95% document-paired bootstrap intervals,10,000 resamples, seed6101516.')
  mechanism=('A는 상속오차 개선이 fixed-B 상쇄 손실에 뒤집힌 계산 패턴, B는 재양자화가 fixed-B 개선을 뒤집은 패턴, C는 frozen 연속 보정의 새 입력 전이 손실, D는 국소 SSE 개선과 NLL 악화가 함께 나온 패턴입니다. 분류는 겹치며 분모는 문서×표적×비영 강도 비교입니다.\n\nEVAL의 A1건은 block4/down_proj/alpha0.5, 문서hash `4f835d09…be32`입니다. T_inherited=−3.673586, T_cancellation=+4.965093, T_cont=+1.291507, T_requant=+4.018703, Δ=+5.310211입니다. 실제 BF16 module SSE 차이는+5.491078이었습니다. 다만 보수적 산술 오차 bound67.454096보다 Δ가 작아 **실행 경로에 대한 부호 보장은 불확정**입니다.\n\n추가 사후 진단은 |SSE_run−SSE|≤2||R||||e||+||e||²를 양 arm에 적용했습니다. 비영 강도2,304행 중2,195행은 Δ 부호가 이 bound를 넘었고109행은 불확정입니다. 원래 FP64 분류를 바꾸거나 원인을 단정하지 않습니다. B12건 중 해당 Δ 부호 bound를 통과한 것은1건입니다.' if ko else 'A denotes inherited-error improvement overturned by fixed-B cancellation loss; B is a re-quantization reversal; C is frozen continuous-correction transfer loss; D combines local SSE improvement with worse NLL. Labels overlap. Denominators count document × target × nonzero-strength comparisons.\n\nThe single EVAL A pattern is block4/down_proj/alpha0.5, document hash `4f835d09…be32`: T_inherited=−3.673586, T_cancellation=+4.965093, T_cont=+1.291507, T_requant=+4.018703, Δ=+5.310211. Actual BF16 module ΔSSE was+5.491078. The conservative arithmetic bound67.454096 exceeds Δ, so its runtime sign guarantee remains unresolved.\n\nA supplementary post-hoc diagnostic applies |SSE_run−SSE|≤2||R||||e||+||e||² to both arms. Of2,304 nonzero-strength rows,2,195 exceed the Δ-sign bound;109 remain unresolved. This does not relabel the original FP64 patterns or establish a unique cause. Only1 of the12 B rows exceeds that Δ-sign bound.')
  resources=(f"측정은 RTX5080 SM120, Torch2.13.0+cu130, Transformers5.17.0에서 수행했습니다. 보수적 worker wall은 **{receipt['wall_seconds']:.3f}초**, runner 내부 구간은344.235초입니다. GPU busy 시간·TTFT·TPOT는 측정하지 않았습니다.\n\n실측 파일 크기: o_proj **1,179,684B**, down_proj **1,769,508B**, 각 표적의5개 alpha에서 동일합니다. Torch peak allocated는{audit['peak_allocated_bytes']:,}B, peak reserved는{audit['peak_reserved_bytes']:,}B입니다. CUDA free/total의 동기화된 사후 표본 중 최대 사용량은{audit['max_device_used_sample_bytes']:,}B이며, 연속 감시한 Windows 전체 peak가 아닙니다." if ko else f"Executed on RTX5080 SM120, Torch2.13.0+cu130 and Transformers5.17.0. Conservative worker wall: **{receipt['wall_seconds']:.3f}s**; inner runner interval344.235s. GPU busy time, TTFT and TPOT were not measured.\n\nActual core files: **1,179,684B** for o_proj and **1,769,508B** for down_proj, identical across five strengths at each target. Torch peak allocated:{audit['peak_allocated_bytes']:,}B; peak reserved:{audit['peak_reserved_bytes']:,}B. Maximum post-forward CUDA used-memory sample:{audit['max_device_used_sample_bytes']:,}B, not a continuously monitored Windows peak.")
  conclusion=('이 고정 설정에서 CAL의 국소 오차만 보고 고른 강도는 EVAL의 국소 오차 순위를 유지하지 못했습니다. 보정·재양자화·새 입력·downstream 점수가 서로 다른 현상임을 실제 저장 파일과 전체 forward로 연결한 것이 이번 결과입니다. 모든 보정이 나쁘거나 다른 모델에도 같은 빈도로 일어난다는 결론은 아닙니다. P1 완료는 좋은 점수와 별개입니다.' if ko else 'In this fixed setup, strengths chosen using CAL local error did not preserve the EVAL local-error ordering. The result connects compensation, actual re-quantization, new inputs and downstream scores through saved artifacts and full forwards. It does not imply every correction is harmful or estimate prevalence on other models. Execution completion is separate from quality improvement.')
  verification=('기존 P0 고유15개 테스트를 이번에 다시 통과했습니다. 새 고유15개를 추가한 것이 아닙니다. P0 MC는 재실행하지 않았으며 당시 lambda=0입니다. 독립 stdlib scalar auditor는2,880행과 선택·분모·집계를 검산했고, 새 CPU 프로세스는30개 artifact를 독립 디코딩했습니다. 비공개 작은 표본8건은 Torch CPU FP64로 전체 행렬과 cast를 재검산했습니다. 원 weight/X/Z/full logits가 제외된 검토본은 GPU NLL/KL 연산을 새로 재현하지 않습니다.\n\n사용자 승인은 기존 WSL snapshot의 읽기 전용 재사용에 한정합니다. 실제 전체 로컬 weight SHA256은 기존 cache blob 식별자와 일치했습니다. 외부 공식 digest를 새로 확보한 인증과 구분합니다. 원본 snapshot·기존 P0/실패·환경을 보존하며 P2/P3와 원격 게시는 미실행입니다.' if ko else 'The existing15 unique P0 tests passed again; they are not15 new tests. P0 MC was not rerun; its lambda was0. The independent stdlib auditor checked2,880 scalar rows, selection, pairing and denominators. A fresh CPU process independently decoded30 artifacts;8 private-array samples were checked with Torch CPU FP64. The review without private weights/activations/logits does not rerun GPU NLL/KL computation.\n\nUser authorization covers read-only reuse of the existing WSL snapshot. Full local weight SHA256 matches the existing cache blob identity; this is distinct from newly obtaining an external official digest. The original snapshot, P0/history and environment are preserved. P2/P3 and remote publication were not run.')
  toc='\n'.join(f'{i+1}. [{h}](#s{i+1})' for i,h in enumerate(head));report=f'# {title}\n\n'+('[English](REPORT.md)' if ko else '[한국어](REPORT.ko.md)')+'\n\n'+toc+'\n\n'
  bodies=[easy+'\n\n'+intro,('Q1 상쇄 / Q2 실제 재양자화 / Q3 CAL→새 문서 전이를 따로 판정했습니다. 작은 스칼라 반례와 dither는 기존 P0 결과이며 이번 LLM 결과와 합치지 않습니다.' if ko else 'Assessed Q1 cancellation, Q2 actual re-quantization and Q3 CAL-to-new-document transfer separately. Scalar counterexamples/dither remain historical P0 evidence, separate from these LLM observations.'),contract+'\n\n'+boundary,protocol,dataset+'\n\n'+resources,findings+'\n\n'+table+'\n\n![All six target curves](figures/p1_r2/fig2_components.svg)\n\n[All120 target/strength/split summaries](results/p1_r2/summary.csv) · [Raw2880 rows](results/p1_r2/cells)\n\n![CAL/EVAL ranks](figures/p1_r2/fig3_transfer.svg)',mechanism+'\n\n'+class_table+'\n\n![All target local error versus downstream NLL](figures/p1_r2/fig4_local_nll.svg)',conclusion,verification+f'\n\nExecution source SHA256: `{freeze}`. Base Git SHA: `09194c3f2e2c991feff5b6abab0cf8ab81a07052`. These identify different objects.\n\n[Reproduce](REPRODUCE.md) · [Independent audit](results/p1_r2/independent_audit.json) · [Source audit](references/source_audit.json) · [Original P0 report](publication/original_pre_p1/REPORT'+suffix+'.md).\n\n[Guo2026 v1](https://arxiv.org/html/2610.16020v1) motivates this independent ridge/RTN diagnostic. This is not official full QEP reproduction or a new quantizer. Codex assisted implementation and reporting; no independent human review is claimed.']
  for i,(h,b) in enumerate(zip(head,bodies)):report+=f'<a id="s{i+1}"></a>\n## {h}\n\n{b}\n\n'
  (CASE/('REPORT'+suffix+'.md')).write_text(report)
